import re

def statistiche_mesh(output):
    trovate = re.findall(r"(\d+) nodes (\d+) elements", output)
    if not trovate:
        raise RuntimeError("mesh non riuscita")
    nodi, elementi = trovate[-1]
    return int(nodi), int(elementi)

print(statistiche_mesh("Info : 1842 nodes 3790 elements"))
